alter table public.profile enable row level security;
alter table public.want enable row level security;
alter table public.offer enable row level security;
alter table public.place enable row level security;
alter table public.push_token enable row level security;
alter table public.photo enable row level security;
alter table public.chat_thread enable row level security;
alter table public.message enable row level security;
alter table public.rating enable row level security;
create policy place_select on public.place as PERMISSIVE for SELECT to authenticated using (true);
create policy profile_select on public.profile as PERMISSIVE for SELECT to authenticated using (true);
create policy profile_insert on public.profile as PERMISSIVE for INSERT to authenticated with check ((id = ( SELECT auth.uid() AS uid)));
create policy profile_update on public.profile as PERMISSIVE for UPDATE to authenticated using ((id = ( SELECT auth.uid() AS uid))) with check ((id = ( SELECT auth.uid() AS uid)));
create policy want_select on public.want as PERMISSIVE for SELECT to authenticated using (((owner_id = ( SELECT auth.uid() AS uid)) OR ((status = 'aktiv'::want_status) AND (expires_at > now())) OR private.has_offer_on_want(id)));
create policy want_insert on public.want as PERMISSIVE for INSERT to authenticated with check (((owner_id = ( SELECT auth.uid() AS uid)) AND (status = 'aktiv'::want_status)));
create policy want_update on public.want as PERMISSIVE for UPDATE to authenticated using (((owner_id = ( SELECT auth.uid() AS uid)) AND (status <> 'erledigt'::want_status))) with check (((owner_id = ( SELECT auth.uid() AS uid)) AND (status <> 'erledigt'::want_status)));
create policy want_delete on public.want as PERMISSIVE for DELETE to authenticated using ((owner_id = ( SELECT auth.uid() AS uid)));
create policy offer_select on public.offer as PERMISSIVE for SELECT to authenticated using (((seller_id = ( SELECT auth.uid() AS uid)) OR private.is_want_owner(want_id)));
create policy offer_insert on public.offer as PERMISSIVE for INSERT to authenticated with check (((seller_id = ( SELECT auth.uid() AS uid)) AND (status = 'neu'::offer_status) AND private.want_open_for_offer(want_id)));
create policy offer_update on public.offer as PERMISSIVE for UPDATE to authenticated using (((seller_id = ( SELECT auth.uid() AS uid)) AND (status = 'neu'::offer_status))) with check (((seller_id = ( SELECT auth.uid() AS uid)) AND (status = 'neu'::offer_status)));
create policy photo_select on public.photo as PERMISSIVE for SELECT to authenticated using (private.can_read_offer(offer_id));
create policy photo_insert on public.photo as PERMISSIVE for INSERT to authenticated with check (private.is_own_new_offer(offer_id));
create policy photo_delete on public.photo as PERMISSIVE for DELETE to authenticated using (private.is_own_new_offer(offer_id));
create policy chat_thread_select on public.chat_thread as PERMISSIVE for SELECT to authenticated using (((( SELECT auth.uid() AS uid) = buyer_id) OR (( SELECT auth.uid() AS uid) = seller_id)));
create policy chat_thread_update on public.chat_thread as PERMISSIVE for UPDATE to authenticated using ((((( SELECT auth.uid() AS uid) = buyer_id) OR (( SELECT auth.uid() AS uid) = seller_id)) AND (closed_at IS NULL))) with check ((((( SELECT auth.uid() AS uid) = buyer_id) OR (( SELECT auth.uid() AS uid) = seller_id)) AND (closed_at IS NULL)));
create policy message_select on public.message as PERMISSIVE for SELECT to authenticated using (private.is_thread_member(thread_id));
create policy message_insert on public.message as PERMISSIVE for INSERT to authenticated with check (((sender_id = ( SELECT auth.uid() AS uid)) AND (read_at IS NULL) AND private.is_thread_member(thread_id)));
create policy rating_select on public.rating as PERMISSIVE for SELECT to authenticated using (true);
create policy rating_insert on public.rating as PERMISSIVE for INSERT to authenticated with check (((from_user_id = ( SELECT auth.uid() AS uid)) AND private.can_rate(thread_id, to_user_id)));
create policy push_token_all on public.push_token as PERMISSIVE for ALL to authenticated using ((profile_id = ( SELECT auth.uid() AS uid))) with check ((profile_id = ( SELECT auth.uid() AS uid)));